-- Customer intelligence
SELECT Customer_ID, Customer_Segment, Region, COUNT(DISTINCT Order_ID) AS orders, ROUND(SUM(Revenue),2) AS revenue, ROUND(SUM(Profit),2) AS profit, ROUND(SUM(Revenue)/NULLIF(COUNT(DISTINCT Order_ID),0),2) AS average_order_value FROM sales_transactions WHERE Order_Status <> 'Cancelled' GROUP BY Customer_ID, Customer_Segment, Region ORDER BY revenue DESC;
SELECT Customer_Segment, COUNT(DISTINCT Customer_ID) AS customers, ROUND(SUM(Revenue),2) AS revenue, ROUND(SUM(Profit),2) AS profit, ROUND(SUM(Revenue)/NULLIF(COUNT(DISTINCT Customer_ID),0),2) AS revenue_per_customer FROM sales_transactions WHERE Order_Status <> 'Cancelled' GROUP BY Customer_Segment ORDER BY revenue DESC;
WITH customer_orders AS (SELECT Customer_ID, COUNT(DISTINCT Order_ID) AS orders FROM sales_transactions WHERE Order_Status <> 'Cancelled' GROUP BY Customer_ID) SELECT CASE WHEN orders = 1 THEN 'One-time' ELSE 'Returning' END AS customer_type, COUNT(*) AS customers FROM customer_orders GROUP BY 1;
